import { Pipe, PipeTransform } from '@angular/core';

/**
 * Minimal pipes for the RAG chat widget.
 *
 * The assistant answer is generated by the API strictly from the retrieved
 * portfolio context (the API prompt guardrail), so `markdown` renders it as
 * HTML with a small set of safe common elements. For a stricter contract the
 * API could return HTML-escaped text and this pipe could be replaced with a
 * DOMParser-based sanitizer, but that is out of scope for the v1 chat surface.
 *
 * Use: `answer | markdown`
 */
@Pipe({ name: 'markdown', standalone: true })
export class MarkdownPipe implements PipeTransform {
  transform(value: unknown): string {
    if (value == null) {
      return '';
    }
    const text = String(value);
    // Paragraphs first, then inline emphasis + links + code.
    return text
      .split(/\n\s*\n/)
      .map((para) => {
        const inline = para
          // inline code spans
          .replace(/`([^`]+)`/g, '<code>$1</code>')
          // bold
          .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
          // italic
          .replace(/\*([^*]+)\*/g, '<em>$1</em>')
          // autolink + href
          .replace(/https?:\/\/[^\s<]+/g, (url) => `<a href="${url}" target="_blank" rel="noopener noreferrer">${url}</a>`);
        return `<p>${inline}</p>`;
      })
      .join('');
  }
}
